def candidate(q, k, v):
    b,h,n,d = q.shape
    block = 128
    def step(i):
        qt = jax.lax.dynamic_slice_in_dim(q, i*block, block, axis=2)
        s = jnp.einsum('bhqd,bhkd->bhqk',qt,k) * (d ** -0.5)
        mask = (i*block+jnp.arange(block))[:,None] >= jnp.arange(n)[None,:]
        p = jax.nn.softmax(jnp.where(mask,s,-jnp.inf),axis=-1)
        return jnp.einsum('bhqk,bhkd->bhqd',p,v)
    out = jax.lax.map(step,jnp.arange(n//block))
    return out.transpose(1,2,0,3,4).reshape(b,h,n,d)

def candidate(q,k,v):
    n,d = q.shape[-2:]
    block = 256
    outputs = []
    for start in range(0,n,block):
        end = min(start+block,n)
        s = jnp.einsum('bhqd,bhkd->bhqk',q[:,:,start:end,:],k[:,:,:end,:]) * (d**-0.5)
        mask = jnp.arange(start,end)[:,None] >= jnp.arange(end)[None,:]
        p = jax.nn.softmax(jnp.where(mask,s,-jnp.inf),axis=-1)
        outputs.append(jnp.einsum('bhqk,bhkd->bhqd',p,v[:,:,:end,:]))
    return jnp.concatenate(outputs,axis=2)

