            mask = (start+i*64+jnp.arange(64))[:,None]>=jnp.arange(end)[None,:]
            p = jax.nn.softmax(jnp.where(mask,s,-jnp.inf),axis=-1)
            return jnp.einsum('bhqk,bhkd->bhqd',p,v[:,:,:end,:])
        out = jax.lax.map(step,jnp.arange(4))
        outputs.append(out.transpose(1,2,0,3,4).reshape(b,h,256,d))
    return jnp.concatenate(outputs,axis=2)

def candidate(q,k,v):
    n,d = q.shape[-2:]
    outputs = []
    for start in range(0,n,256):
        end = min(start+256,n)
        s = jnp.einsum('bhqd,bhkd->bhqk',q[:,:,start:end,:],k[:,:,:end,:])*(d**-0.5)
        mask = jnp.arange(start,end)[:,None]>=jnp.arange(end)[None,:]
        s = jnp.where(mask,s,-jnp.inf)
        p = jnp.exp(s-jnp.max(s,axis=-1,keepdims=True))
        denominator = jnp.sum(p,axis=-1,keepdims=True)
        numerator = jnp.einsum('bhqk,bhkd->bhqd',p,v[:,:,:end,:])
        outputs.append(numerator/denominator)
    return jnp.concatenate(outputs,axis=2)

