    b, h, n, d = q.shape
    def block(i):
        qq = jax.lax.dynamic_slice_in_dim(q, i * 128, 128, axis=2)
        scores = jnp.einsum('bhqd,bhkd->bhqk', qq, k) * (d ** -0.5)
        mask = i * 128 + jnp.arange(128)[:, None] >= jnp.arange(n)[None, :]
        weights = jax.nn.softmax(jnp.where(mask, scores, -jnp.inf), axis=-1)
        return jnp.einsum('bhqk,bhkd->bhqd', weights, v)
    out = jax.lax.map(block, jnp.arange(n // 128))
    return out.transpose(1, 2, 0, 3, 4).reshape(q.shape)

