def candidate(x, ln1_g, ln1_b, w_qkv, w_o, ln2_g, ln2_b, w_1, w_2):
    def ln(z,g,b):
        m=jnp.mean(z,-1,keepdims=True)
        v=jnp.mean((z-m)**2,-1,keepdims=True)
        return (z-m)/jnp.sqrt(v+1e-5)*g+b
    b,s,d=x.shape
    q,k,v=[t.reshape(b,s,d//64,64).transpose(0,2,1,3) for t in jnp.split(ln(x,ln1_g,ln1_b)@w_qkv,3,-1)]
    parts=[]
    for start in range(0,s,256):
        end=min(start+256,s)
        scores=jnp.einsum('bhqd,bhkd->bhqk',q[:,:,start:end,:],k[:,:,:end,:])*0.125
        scores=jnp.where(jnp.arange(start,end)[:,None]>=jnp.arange(end)[None,:],scores,-jnp.inf)
        parts.append(jnp.einsum('bhqk,bhkd->bhqd',jax.nn.softmax(scores,-1),v[:,:,:end,:]))
    a=jnp.concatenate(parts,axis=2).transpose(0,2,1,3).reshape(b,s,d)
    y=x+a@w_o
    def mlp(z):
        return z+jax.nn.gelu(ln(z,ln2_g,ln2_b)@w_1,approximate=False)@w_2
    return jax.lax.map(mlp,y)

